        return $this->cache->remember('native-enriched', $slot, $fingerprint, Graph::class, fn (): Graph => CallEnrichment::of(
            $this->cache->remember('native-graph', $slot, $fingerprint, Graph::class, $build),
            $this->phpVersion,
            $this->cache,
        ));
    }

