    private \PHPStan\PhpDoc\TypeNodeResolver $typeNodeResolver;
    public function __construct(Lexer $typeLexer, TypeParser $typeParser, \PHPStan\PhpDoc\TypeNodeResolver $typeNodeResolver)
    {
